using System.Collections.Generic;
using UnityEngine;
namespace Abyss.Story {
public class WarEnvironment:MonoBehaviour {
 public int Stage=>previewStage>=0?previewStage:(story.thirdChapter.Started?2:story.secondChapter.Started?1:0);
 public float canFrequencyMultiplier=3.5f;public int announcementWaste=10,journeyWaste=52;public float wasteInterval=1.3f;float nextCan;readonly List<GameObject> localDecor=new();
 public UnderwaterDayStory story;public Sprite[] waste,skeletons;public Sprite vessel;public Font pixelFont;
 [Range(-1,3)]public int previewStage=-1;public float transitionSpeed=.25f;public int maximumWaste=64,maximumCorpses=8;
 public Shader pollutionShader;Material pollutionMaterial;MaterialPropertyBlock pollutionBlock;
 readonly List<SpriteRenderer> backgrounds=new();readonly List<Color> original=new();readonly List<GameObject> litter=new();readonly List<GameObject> bones=new();float pollution,nextWaste;int deaths;
 void Start(){if(pollutionShader){pollutionMaterial=new Material(pollutionShader);pollutionBlock=new MaterialPropertyBlock();}foreach(var r in FindObjectsByType<SpriteRenderer>(FindObjectsSortMode.None)){if(r.transform.IsChildOf(transform)||r==story.player.visual)continue;if(r.GetComponent<RoamingCreature>()||r.GetComponent<DistantSwimmer>()||r.GetComponentInParent<StorySwimmer>())continue;if(r.sortingOrder<8||r.name.ToLowerInvariant().Contains("gradient")||r.name.ToLowerInvariant().Contains("distant")||r.name.Contains("Sky")||r.name.ToLowerInvariant().Contains("shaft")){backgrounds.Add(r);original.Add(r.color);if(pollutionMaterial)r.material=pollutionMaterial;}}if(pixelFont)story.ui.UseFont(pixelFont);
 var ship=Create("Static surface treatment vessel",vessel,new Vector2(-45,story.player.surfaceY+.9f),17,8);ship.transform.SetParent(transform);var discharge=GetComponent<BrineDischarge>();if(discharge)discharge.vesselTransform=ship.transform;MakeDeposit();
 for(int i=0;i<5;i++){var bone=Create("Floating fish skeleton",skeletons[i%4],new Vector2(story.Discovery.x+new[]{-8f,1.8f,7f,-10.5f,10f}[i],story.player.surfaceY-(i<3?.08f:.42f)),.8f,14);bones.Add(bone.gameObject);bone.gameObject.SetActive(false);}
 }
 void MakeDeposit(){for(int i=0;i<10;i++){var r=Create("Discharge skeleton",skeletons[i%4],new Vector2(-62+(i%5)*4,i<3?story.player.surfaceY-.4f:i<7?4-i*2:-32),.5f,12);r.transform.rotation=Quaternion.Euler(0,0,(i%3-1)*12);if(i>=7)Ground(r);localDecor.Add(r.gameObject);}for(int i=0;i<8;i++){var r=Create("Discharge area waste",waste[i<3?new[]{0,1,3}[i]:i>=6?(i==6?2:5):i%6],new Vector2(-65+i*3,i<3?story.player.surfaceY-.2f:i<6?-i*2:-31.8f),.55f,12);if(i<3){var drift=r.gameObject.AddComponent<WarDebris>();drift.surface=story.player.surfaceY;}if(i>=6)Ground(r);localDecor.Add(r.gameObject);}}
 void Ground(SpriteRenderer r){foreach(var hit in Physics2D.RaycastAll(new Vector2(r.transform.position.x,story.player.surfaceY),Vector2.down,60))if(hit.collider&&!hit.collider.isTrigger&&!hit.collider.attachedRigidbody){var p=r.transform.position;p.y=hit.point.y+r.bounds.extents.y-.03f;r.transform.position=p;break;}}
 float HeavySpawnX(){float lead=Mathf.Clamp((story.player.surfaceY-story.player.transform.position.y)/1.4f*story.player.CurrentSpeed,25,150);return Mathf.Clamp(story.player.transform.position.x+lead+Random.Range(-20,20),-230,235);}
 SpriteRenderer Create(string name,Sprite sprite,Vector2 at,float width,int order){var go=new GameObject(name);go.transform.SetParent(transform,false);go.transform.position=at;var r=go.AddComponent<SpriteRenderer>();r.sprite=sprite;r.sortingOrder=order;go.transform.localScale=Vector3.one*width/sprite.bounds.size.x;return r;}
 void Update(){int stage=Stage;foreach(var item in localDecor)item.SetActive(stage>0);pollution=Mathf.MoveTowards(pollution,stage,transitionSpeed*Time.deltaTime);for(int i=0;i<backgrounds.Count;i++)if(backgrounds[i]){if(pollutionBlock!=null){backgrounds[i].GetPropertyBlock(pollutionBlock);pollutionBlock.SetFloat("_Pollution",Mathf.Clamp01(pollution*.4f));backgrounds[i].SetPropertyBlock(pollutionBlock);}else backgrounds[i].color=Color.Lerp(original[i],original[i]*new Color(.49f,.66f,.47f,1),pollution/3);}
 foreach(var bone in bones)bone.SetActive(story.Stage>=UnderwaterDayStage.FollowToSurface);
 if(stage>0&&story.thirdChapter.hazards.Running&&Time.time>nextCan){nextCan=Time.time+10/canFrequencyMultiplier;GameObject can;if(litter.Count>=Mathf.Min(maximumWaste,stage==1?announcementWaste:journeyWaste)){can=litter[0];litter.RemoveAt(0);litter.Add(can);}else{can=Create("Sinking can",waste[2],Vector2.zero,.65f,13).gameObject;litter.Add(can);}can.GetComponent<SpriteRenderer>().sprite=waste[2];can.transform.position=new Vector2(HeavySpawnX(),story.player.surfaceY-.1f);var d=can.GetComponent<WarDebris>()??can.AddComponent<WarDebris>();d.surface=story.player.surfaceY;d.heavy=true;d.ResetMotion();}

 int target=stage==0?0:stage==1?announcementWaste:journeyWaste;while(litter.Count>target){Destroy(litter[^1]);litter.RemoveAt(litter.Count-1);}if(stage>=2&&litter.Count>=target&&Time.time>nextWaste){foreach(var item in litter)if(item.transform.position.x<story.player.transform.position.x-55){item.transform.position=new Vector2(story.player.transform.position.x+(Random.value>.5f?1:-1)*Random.Range(20,28),item.GetComponent<WarDebris>().suspended&&!item.GetComponent<WarDebris>().heavy?Mathf.Clamp(story.player.transform.position.y+Random.Range(-6,6),-29,story.player.surfaceY-2):story.player.surfaceY-.1f);item.GetComponent<WarDebris>()?.ResetMotion();nextWaste=Time.time+wasteInterval/stage;break;}}if(stage==0){deaths=0;foreach(var corpse in FindObjectsByType<WarFishCorpse>(FindObjectsSortMode.None))Destroy(corpse.gameObject);}
 if(stage>0&&litter.Count<Mathf.Min(maximumWaste,target)&&Time.time>nextWaste){nextWaste=Time.time+wasteInterval/Mathf.Max(1,stage);int index=litter.Count%waste.Length;var at=new Vector2(Mathf.Clamp(story.player.transform.position.x+Random.Range(-20,20),-230,230),story.player.surfaceY-.1f);var r=Create("War debris (harmless)",waste[index],at,Random.Range(.45f,.85f),13);var drift=r.gameObject.AddComponent<WarDebris>();drift.surface=story.player.surfaceY;drift.heavy=index==2||index==5;if(drift.heavy){var spawn=r.transform.position;spawn.x=HeavySpawnX();r.transform.position=spawn;}if(!drift.heavy&&((stage>=2&&litter.Count%2==0)||(stage==1&&litter.Count%4==0))){drift.suspended=true;var p=r.transform.position;p.y=stage==1?Mathf.Clamp(story.player.transform.position.y+Random.Range(-4,4),-29,story.player.surfaceY-2):Random.Range(-29,story.player.surfaceY-2);r.transform.position=p;}litter.Add(r.gameObject);}
 }
 void OnDestroy(){if(pollutionMaterial)Destroy(pollutionMaterial);}
 public bool StrikeFish(Vector2 from,Vector2 to){if(FindObjectsByType<WarFishCorpse>(FindObjectsSortMode.None).Length>=maximumCorpses||!story.thirdChapter.Started)return false;foreach(var fish in FindObjectsByType<RoamingCreature>(FindObjectsSortMode.None)){if(!fish.enabled||fish.GetComponent<WarFishCorpse>()||fish.definition.family!=HabitatFamily.ReefFish)continue;Vector2 p=fish.transform.position;var delta=to-from;float t=Mathf.Clamp01(Vector2.Dot(p-from,delta)/Mathf.Max(.0001f,delta.sqrMagnitude));if(Vector2.Distance(p,from+delta*t)>.65f)continue;fish.enabled=false;var corpse=fish.gameObject.AddComponent<WarFishCorpse>();corpse.surface=story.player.surfaceY;deaths++;return true;}return false;}
}
public class WarDebris:MonoBehaviour {
 public void ResetMotion(){landed=false;restY=transform.position.y;}
 public bool heavy,suspended;public float surface;float restY;bool landed;float phase;
 void Start(){phase=Random.value*6;restY=transform.position.y;}
 void Update(){if(!heavy){var p=transform.position;p.y=(suspended?restY:surface-.15f)+Mathf.Sin(Time.time*.6f+phase)*.05f;transform.position=p;return;}if(landed)return;transform.Rotate(0,0,Time.deltaTime*8);Vector2 from=transform.position,to=from+Vector2.down*Time.deltaTime*1.4f;foreach(var hit in Physics2D.RaycastAll(from,Vector2.down,.16f+Time.deltaTime*1.4f))if(hit.collider&&!hit.collider.isTrigger&&!hit.collider.attachedRigidbody){transform.position=hit.point+Vector2.up*.12f;landed=true;return;}transform.position=to;}
}
public class WarFishCorpse:MonoBehaviour {
 public float surface;float age;SpriteRenderer visual;Color original;
 void Start(){visual=GetComponent<SpriteRenderer>();original=visual.color;original.a=1;}
 void Update(){age+=Time.deltaTime;visual.color=age<.15f?new Color(1,.6f,.6f,original.a):original;transform.rotation=Quaternion.Euler(0,0,Mathf.SmoothStep(0,180,age));var p=transform.position;p.y=Mathf.Min(surface-.1f,p.y+Time.deltaTime*.85f);transform.position=p;if(age>78){var c=visual.color;c.a*=Mathf.Clamp01((80-age)/2);visual.color=c;}if(age>80)Destroy(gameObject);}
}
}
